import sys, re, sqlite3
sys.path.insert(0,'scripts')
import dbcore

con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)

# Reconstruct the OLD (pre-fix) check_values logic inline for comparison, without
# touching the fixed function.
def old_check_values(conn, table, column):
    row = conn.execute(\"SELECT sql FROM sqlite_master WHERE type='table' AND name=?\", (table,)).fetchone()
    if not row or not row[0]:
        return set()
    m = re.search(
        r'CHECK\s*\(\s*(?:%s\s+IS\s+NULL\s+OR\s+)?%s\s+IN\s*\(([^)]*)\)'
        % (re.escape(column), re.escape(column)), row[0], re.I)
    if not m:
        return set()
    return {v.strip().strip(chr(39)+chr(34)) for v in m.group(1).split(',') if v.strip()}

tables = [r[0] for r in con.execute(\"select name from sqlite_master where type='table'\")]
changed = []
unchanged_nonempty = 0
for t in tables:
    cols = [r[1] for r in con.execute(f'PRAGMA table_info(\"{t}\")')]
    for c in cols:
        before = old_check_values(con, t, c)
        after = dbcore.check_values(con, t, c)
        if before or after:
            if before != after:
                changed.append((t, c, before, after))
            else:
                unchanged_nonempty += 1

print('Columns with a non-empty CHECK-derived vocabulary (before or after):', len(changed)+unchanged_nonempty)
print('Unchanged (identical before/after):', unchanged_nonempty)
print()
print('CHANGED columns (%d):' % len(changed))
for t,c,b,a in changed:
    print(' ', t+'.'+c)
    print('    before:', sorted(b))
    print('    after :', sorted(a))
"
